class Solution {
    public String[] uncommonFromSentences(String s1,String s2){
        String[] words=(s1+" "+s2).split(" ");
        Map<String,Integer> frequency=new HashMap<>();
        for(String word:words)frequency.merge(word,1,Integer::sum);
        List<String> answer=new ArrayList<>();
        for(String word:words)if(frequency.get(word)==1)answer.add(word);
        return answer.toArray(new String[0]);
    }
}

code.kotlin:
class Solution {
    fun uncommonFromSentences(s1:String,s2:String):Array<String>{
        val words=(s1+" "+s2).split(' ');
        val frequency=words.groupingBy{
            it
        }.eachCount();
        return words.filter{
            frequency[it]==1
        }.toTypedArray()
    }
}

code.cpp:
class Solution {
    public: vector<string> uncommonFromSentences(string s1,string s2){
        stringstream stream(s1+" "+s2);
        vector<string> words,answer;
        unordered_map<string,int> frequency;
        string word;
        while(stream>>word){
            words.push_back(word);
            ++frequency[word];
        }
        for(string& value:words)if(frequency[value]==1)answer.push_back(value);
        return answer;
    }
};
